from __future__ import annotations

SETUP_PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set up Threatline</title><style>
:root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#e8ebf1;background:#0c0f13}*{box-sizing:border-box}body{margin:0}.shell{max-width:900px;margin:auto;padding:42px 24px 70px}.eyebrow{color:#8793a6;font-size:12px;text-transform:uppercase;letter-spacing:.12em}.hero h1{font-size:40px;letter-spacing:-.04em;margin:8px 0}.hero p{color:#9ca7b8;max-width:720px;line-height:1.55}.card{background:#13171d;border:1px solid #29313b;border-radius:15px;padding:22px;margin-top:18px}.card h2{margin:0 0 6px;font-size:18px}.muted{color:#8995a7;font-size:13px;line-height:1.45}.choices{display:grid;grid-template-columns:1fr 1fr;gap:14px}.provider{border-top:1px solid #29313b;margin-top:18px;padding-top:18px}.provider-head{display:flex;justify-content:space-between;gap:20px;align-items:center}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}.full{grid-column:1/-1}label{display:block;color:#aeb8c7;font-size:12px;margin-bottom:6px}input,select,textarea{width:100%;background:#0f1319;color:#e4e8ef;border:1px solid #303845;border-radius:9px;padding:10px 11px}textarea{min-height:84px;resize:vertical}.check{display:flex;gap:9px;align-items:center}.check input{width:auto}.actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:20px}button,.link{background:#1a1f27;color:#c6cedb;border:1px solid #343c48;border-radius:9px;padding:10px 14px;cursor:pointer;text-decoration:none;font:inherit;font-size:13px}button.primary{background:#edf1f8;color:#10141a;border-color:#edf1f8}.result{margin-top:14px;border-radius:10px;padding:12px;background:#0f1318;border:1px solid #252c36;color:#aeb8c7;font-size:13px;white-space:pre-wrap}.ok{color:#9be7b2}.bad{color:#ffaaa0}.tag{display:inline-block;border:1px solid #33404e;border-radius:999px;padding:5px 8px;color:#aeb8c7;font-size:11px}.existing{color:#9be7b2;font-size:11px;margin-left:5px}@media(max-width:700px){.choices,.grid{grid-template-columns:1fr}.full{grid-column:auto}.hero h1{font-size:32px}}
</style></head><body><main class="shell"><section class="hero"><div class="eyebrow">Threatline workspace</div><h1 id="title">Set up Threatline</h1><p>Start with demo data or connect the systems you already use. Credentials stay server-side in your local Threatline data directory and are never stored in browser storage.</p></section><section id="managed" class="card" hidden><h2>Configuration is managed externally</h2><p class="muted">This Threatline process is configured with environment variables. Browser setup is read-only so local changes cannot silently override deployment configuration.</p><div class="actions"><a class="link" href="/">Return to workspace</a></div></section><section id="setup"><div class="choices"><section class="card"><h2>Explore demo mode</h2><p class="muted">No credentials. Uses simulated operational data so you can explore Today, Queue, investigations, Daily Notes, and Handoff.</p><div class="actions"><button id="demo" class="primary">Use demo workspace</button></div></section><section class="card"><h2>Connect a workspace</h2><p class="muted">Connect Jira, GitHub, or both. Threatline normalizes them behind provider interfaces so the product is not tied to one vendor.</p><div class="tag">Local-first</div> <div class="tag">Explicit writes</div></section></div><section class="card"><h2>Workspace preferences</h2><div class="grid"><div><label for="timezone">Timezone (IANA)</label><input id="timezone" value="UTC" placeholder="America/Chicago"></div></div><div class="provider"><div class="provider-head"><div><strong>Jira</strong><div class="muted">Cloud or Server/Data Center</div></div><label class="check"><input id="jiraEnabled" type="checkbox"> Enable</label></div><div id="jiraFields" class="grid" hidden><div><label for="jiraBase">Base URL</label><input id="jiraBase" placeholder="https://company.atlassian.net"></div><div><label for="jiraAuth">Authentication</label><select id="jiraAuth"><option value="bearer">Personal access token</option><option value="basic">Cloud email + API token</option></select></div><div id="jiraEmailWrap" hidden><label for="jiraEmail">Cloud email</label><input id="jiraEmail" type="email"></div><div><label for="jiraSecret">Credential <span id="jiraSecretState" class="existing"></span></label><input id="jiraSecret" type="password" autocomplete="off" placeholder="Leave blank to keep existing"></div><div class="full"><label for="jiraJql">Queue JQL</label><textarea id="jiraJql">resolution IS EMPTY ORDER BY priority DESC, updated DESC</textarea></div><label class="check"><input id="jiraVerify" type="checkbox" checked> Verify TLS certificates</label></div></div><div class="provider"><div class="provider-head"><div><strong>GitHub</strong><div class="muted">GitHub.com or GitHub Enterprise Server</div></div><label class="check"><input id="githubEnabled" type="checkbox"> Enable</label></div><div id="githubFields" class="grid" hidden><div><label for="githubApi">API URL</label><input id="githubApi" value="https://api.github.com"></div><div><label for="githubWeb">Web URL</label><input id="githubWeb" value="https://github.com"></div><div class="full"><label for="githubRepos">Repositories</label><input id="githubRepos" placeholder="owner/repo, owner/another-repo"></div><div class="full"><label for="githubToken">Token <span id="githubTokenState" class="existing"></span></label><input id="githubToken" type="password" autocomplete="off" placeholder="Leave blank to keep existing"></div><label class="check"><input id="githubVerify" type="checkbox" checked> Verify TLS certificates</label></div></div><div class="actions"><button id="test">Test connections</button><button id="save" class="primary">Save workspace</button><a class="link" href="/">Cancel</a></div><div id="result" class="result" hidden></div></section></section></main><script>
const $=id=>document.getElementById(id),result=$('result');let current={};
function showResult(text,ok=true){result.hidden=false;result.className='result '+(ok?'ok':'bad');result.textContent=text}
async function post(url,payload){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'Request failed');return d}
function toggle(){ $('jiraFields').hidden=!$('jiraEnabled').checked;$('githubFields').hidden=!$('githubEnabled').checked;$('jiraEmailWrap').hidden=$('jiraAuth').value!=='basic'}
function payload(mode='connected'){const providers=[];if($('jiraEnabled').checked)providers.push('jira');if($('githubEnabled').checked)providers.push('github');return {mode,timezone:$('timezone').value.trim()||'UTC',providers,jira:{base_url:$('jiraBase').value.trim(),jql:$('jiraJql').value.trim(),auth_mode:$('jiraAuth').value,email:$('jiraEmail').value.trim(),secret:$('jiraSecret').value,verify_ssl:$('jiraVerify').checked},github:{api_url:$('githubApi').value.trim(),web_url:$('githubWeb').value.trim(),repositories:$('githubRepos').value,token:$('githubToken').value,verify_ssl:$('githubVerify').checked}}}
async function load(){try{const r=await fetch('/api/setup/status'),d=await r.json();current=d;if(d.managed_by_environment){$('setup').hidden=true;$('managed').hidden=false;return}if(d.setup_complete)$('title').textContent='Workspace settings';$('timezone').value=d.timezone||'UTC';const providers=d.providers||[];$('jiraEnabled').checked=providers.includes('jira');$('githubEnabled').checked=providers.includes('github');const j=d.jira||{},g=d.github||{};$('jiraBase').value=j.base_url||'';$('jiraJql').value=j.jql||$('jiraJql').value;$('jiraAuth').value=j.auth_mode||'bearer';$('jiraEmail').value=j.email||'';$('jiraVerify').checked=j.verify_ssl!==false;$('jiraSecretState').textContent=j.secret_configured?'saved':'';$('githubApi').value=g.api_url||'https://api.github.com';$('githubWeb').value=g.web_url||'https://github.com';$('githubRepos').value=(g.repositories||[]).join(', ');$('githubVerify').checked=g.verify_ssl!==false;$('githubTokenState').textContent=g.token_configured?'saved':'';toggle()}catch(e){showResult(e.message,false)}}
$('jiraEnabled').onchange=toggle;$('githubEnabled').onchange=toggle;$('jiraAuth').onchange=toggle;$('demo').onclick=async()=>{try{await post('/api/setup',payload('demo'));location.href='/'}catch(e){showResult(e.message,false)}};$('test').onclick=async()=>{showResult('Testing connections…');try{const d=await post('/api/setup/test',payload());const lines=(d.providers||[]).map(p=>`${p.name}: ${p.health.status} — ${p.health.message}`);const failed=(d.providers||[]).some(p=>p.health.status!=='healthy');showResult(lines.join('\n')||'No providers selected.',!failed)}catch(e){showResult(e.message,false)}};$('save').onclick=async()=>{showResult('Saving workspace…');try{await post('/api/setup',payload());location.href='/'}catch(e){showResult(e.message,false)}};load();
</script></body></html>'''
